"""The order service: one FastAPI app over the SQLite store."""

from fastapi import Depends, FastAPI, HTTPException

import store

app = FastAPI(title="orders")

DISCOUNT_PERCENT = {"gold": 10, "silver": 5}


def database():
    connection = store.connect()
    try:
        yield connection
    finally:
        connection.close()


def find_customer(db, customer_id):
    row = db.execute("SELECT id, name, tier FROM customers WHERE id = ?", (customer_id,)).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="no such customer")
    return row


def discount_for(tier):
    try:
        return DISCOUNT_PERCENT[tier]
    except KeyError:
        return 0


def items_of(db, order_id):
    return db.execute(
        "SELECT product_id, quantity FROM order_items WHERE order_id = ?", (order_id,)
    ).fetchall()


def price_of(db, product_id):
    row = db.execute("SELECT cents FROM products WHERE id = ?", (product_id,)).fetchone()
    return row["cents"]


def product_names(db):
    return {row["id"]: row["name"] for row in db.execute("SELECT id, name FROM products")}


def order_total(db, order_id):
    return sum(price_of(db, item["product_id"]) * item["quantity"] for item in items_of(db, order_id))


@app.get("/customers/{customer_id}/orders")
def list_orders(customer_id: int, names: bool = False, db=Depends(database)):
    customer = find_customer(db, customer_id)
    percent = discount_for(customer["tier"])
    orders = db.execute(
        "SELECT id, placed FROM orders WHERE customer_id = ? ORDER BY placed", (customer_id,)
    ).fetchall()
    labels = product_names(db) if names else None
    result = []
    for order in orders:
        total = order_total(db, order["id"])
        entry = {
            "id": order["id"],
            "placed": order["placed"],
            "total_cents": total * (100 - percent) // 100,
        }
        if labels is not None:
            entry["products"] = [labels[i["product_id"]] for i in items_of(db, order["id"])]
        result.append(entry)
    return {"customer": customer["name"], "orders": result}
"""The SQLite store of the order service: schema, seed data, one connection."""

import sqlite3
from pathlib import Path

DB = Path(__file__).parent / "orders.db"

SCHEMA = """
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT, tier TEXT);
CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT, cents INTEGER);
CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, placed TEXT);
CREATE TABLE order_items (order_id INTEGER, product_id INTEGER, quantity INTEGER);
"""

CUSTOMERS = [(1, "Ana", "gold"), (2, "Bruno", "silver"), (3, "Clara", "trial")]
PRODUCTS = [(1, "notebook", 450), (2, "pen", 120), (3, "stapler", 990), (4, "tape", 260)]


def connect():
    connection = sqlite3.connect(DB)
    connection.row_factory = sqlite3.Row
    return connection


def create():
    """Build the database again, with the same customers, products and orders."""
    DB.unlink(missing_ok=True)
    connection = connect()
    connection.executescript(SCHEMA)
    connection.executemany("INSERT INTO customers VALUES (?, ?, ?)", CUSTOMERS)
    connection.executemany("INSERT INTO products VALUES (?, ?, ?)", PRODUCTS)
    order_id = 0
    for customer_id, how_many in ((1, 4), (2, 3), (3, 12)):
        for n in range(how_many):
            order_id += 1
            connection.execute(
                "INSERT INTO orders VALUES (?, ?, ?)",
                (order_id, customer_id, f"2026-11-{n + 1:02d}"),
            )
            for k in range(1 + order_id % 3):
                connection.execute(
                    "INSERT INTO order_items VALUES (?, ?, ?)",
                    (order_id, 1 + (order_id + k) % 4, 1 + k),
                )
    connection.commit()
    connection.close()
# web-backend: an order service

A small FastAPI service over a SQLite database of customers, products and orders. It has one route:

```
GET /customers/{customer_id}/orders          the customer's orders, each with its total
GET /customers/{customer_id}/orders?names=1  the same, with the product names of each order
```

A gold customer gets 10% off, a silver one 5%.

## Run it

```bash
pip install -r requirements.txt
python main.py        # builds orders.db, asks for the orders of customer 3 through the test client
python main.py 1      # another customer
```

It prints one line:

```
GET /customers/3/orders -> 200, 12 orders
```

## Files

- `store.py`: the schema, the seed data, `connect()`.
- `app.py`: the FastAPI app and its route.
- `main.py`: one request through `fastapi.testclient`.
